add('chart-line','''R{position:relative;transform:translateX(0);anchor-scope:all;border-bottom:1px solid var(--n-3);background:repeating-linear-gradient(to top,var(--n-2) 0 1px,var(--page) 1px 20%)}R .pt{position:absolute;width:0;height:0;bottom:calc(var(--gap-lg) + var(--v)/var(--max) * (100% - 2 * var(--gap-lg)));z-index:1}R .pt b{position:absolute;bottom:var(--gap-sm);left:50%;transform:translateX(-50%);white-space:nowrap;font-size:var(--type-18);font-weight:var(--label-weight)}R .pt span{position:fixed;top:calc(100% - var(--gap));transform:translateX(-50%);font-size:var(--type-16);white-space:nowrap}R .pt b:after{content:'';position:absolute;left:50%;top:calc(100% + 6px);width:9px;height:9px;border-radius:999px;background:var(--page);border:2px solid var(--a1);transform:translate(-50%,-50%)}R .pt:before,R .pt:after{content:'';position:fixed;pointer-events:none;z-index:-1}''')
for n in range(3,13):
 for i in range(1,n+1):
  left=5+90*(i-1)/(n-1)
  add('chart-line',f'R:has(>.pt:nth-child({n}):last-child)>.pt:nth-child({i})'+'{left:'+f'{left:.5f}%;anchor-name:--vectorbox-p{i}'+'}')
  if i<n:
   clear='color-mix(in srgb,var(--a1) 0%,var(--page) 0%)'
   add('chart-line',f'R:has(>.pt:nth-child({n}):last-child)>.pt:nth-child({i}):before'+'{left:anchor(--vectorbox-p'+str(i)+' center);right:calc(100% - anchor(--vectorbox-p'+str(i+1)+' center));top:anchor(--vectorbox-p'+str(i+1)+' center);bottom:calc(100% - anchor(--vectorbox-p'+str(i)+' center));background:linear-gradient(to bottom right,'+clear+' calc(50% - 1px),var(--a1) calc(50% - 1px) calc(50% + 1px),'+clear+' calc(50% + 1px))}')
   add('chart-line',f'R:has(>.pt:nth-child({n}):last-child)>.pt:nth-child({i}):after'+'{left:anchor(--vectorbox-p'+str(i)+' center);right:calc(100% - anchor(--vectorbox-p'+str(i+1)+' center));top:anchor(--vectorbox-p'+str(i)+' center);bottom:calc(100% - anchor(--vectorbox-p'+str(i+1)+' center));background:linear-gradient(to top right,'+clear+' calc(50% - 1px),var(--a1) calc(50% - 1px) calc(50% + 1px),'+clear+' calc(50% + 1px))}')
